class PurchaseRequest(models.Model):
    _name = 'x.purchase.request'
    _description = 'Purchase Request'
    _inherit = ['mail.thread', 'mail.activity.mixin']   # chatter + tracking

    name = fields.Char(default=lambda self: _('New'), copy=False, readonly=True)
    state = fields.Selection([
        ('draft', 'Draft'), ('confirmed', 'Confirmed'), ('done', 'Done'), ('cancel', 'Cancelled'),
    ], default='draft', required=True, tracking=True, copy=False)

    @api.model_create_multi            # Odoo 13+: create() ALWAYS takes a list of dicts
    def create(self, vals_list):
        for vals in vals_list:
            if vals.get('name', _('New')) == _('New'):
                vals['name'] = self.env['ir.sequence'].next_by_code('x.purchase.request') or _('New')
        return super().create(vals_list)

    # button methods: type="object" in the view, act on self (a recordset!)
    def action_confirm(self):
        for rec in self:
            if rec.state != 'draft':
                raise UserError(_("Only draft requests can be confirmed."))
            rec.state = 'confirmed'
        return True

    def action_cancel(self):
        self.filtered(lambda r: r.state != 'done').write({'state': 'cancel'})

    def action_reset_draft(self):
        self.write({'state': 'draft'})

    def unlink(self):
        if any(rec.state not in ('draft', 'cancel') for rec in self):
            raise UserError(_("You can only delete draft or cancelled requests."))
        return super().unlink()

# data/ir_sequence_data.xml (noupdate="1"):
# <record id="seq_x_purchase_request" model="ir.sequence">
#     <field name="name">Purchase Request</field>
#     <field name="code">x.purchase.request</field>
#     <field name="prefix">PR/%(year)s/</field>
#     <field name="padding">5</field>
#     <field name="company_id" eval="False"/>
# </record>

# Odoo 17+: _read_group(domain, groupby=(), aggregates=(), having=(), offset=0, limit=None, order=None) # returns a list of TUPLES: (groupby values..., aggregate values...) rows = self.env['sale.order']._read_group( [('state', '=', 'sale'), ('date_order', '>=', date_from)], ['partner_id', 'date_order:month'], # groupby (with granularity) ['amount_total:sum', '__count'], # aggregates order='amount_total:sum desc', limit=10) for partner, month, amount_sum, count in rows: ... # partner is a res.partner RECORD, month a date
# the public read_group (dicts, like the old API) still exists for RPC/UI code: data = self.env['sale.order'].read_group( [('state', '=', 'sale')], ['amount_total:sum'], ['partner_id'], lazy=False) # -> [{'partner_id': (id, 'Name'), 'amount_total': 1234.0, '__count': 3, '__domain': [...]}, ...]
# Dashboard method: sudo() the reads, return EVERYTHING the UI shows @api.model def get_dashboard_data(self, days=30): Order = self.env['sale.order'].sudo() date_from = fields.Date.today() - timedelta(days=days) rows = Order._read_group([('date_order', '>=', date_from)], ['partner_id'], ['amount_total:sum', '__count']) return { 'kpis': {'orders': sum(c for _p, _a, c in rows), 'revenue': sum(a for _p, a, _c in rows)}, 'by_partner': [{'label': p.display_name, 'value': a} for p, a, _c in rows], }

class LibraryLoan(models.Model):
    _name = 'library.loan'
    _description = 'Library Loan'

    book_id = fields.Many2one('library.book', required=True)
    # PREFERRED over @api.onchange: a computed field that the user may still edit
    # (store=True, readonly=False). Works in the UI AND in create()/write() from code.
    date_due = fields.Date(compute='_compute_date_due', store=True, readonly=False)
    note = fields.Text()

    @api.depends('book_id')
    def _compute_date_due(self):
        for loan in self:
            loan.date_due = fields.Date.context_today(loan) + timedelta(days=14)

    # @api.onchange is UI-only (not triggered by code) — reserve it for warnings/domains
    @api.onchange('book_id')
    def _onchange_book_id(self):
        if self.book_id and self.book_id.state == 'borrowed':
            return {'warning': {'title': _("Already out"),
                                'message': _("This book is currently borrowed.")}}

    @api.model
    def default_get(self, fields_list):
        defaults = super().default_get(fields_list)
        # context defaults from an action: context="{'default_book_id': active_id}"
        if 'note' in fields_list and not defaults.get('note'):
            defaults['note'] = _("Standard 14-day loan")
        return defaults

    def copy(self, default=None):
        default = dict(default or {}, note=_("%s (copy)", self.note or ''))
        return super().copy(default)

import logging
from odoo import api, fields, models, _
from odoo.exceptions import UserError, ValidationError, AccessError

_logger = logging.getLogger(__name__)      # module-level, once per file

class Thing(models.Model):
    _name = 'x.thing'
    _description = 'Thing'

    qty = fields.Float()

    @api.constrains('qty')
    def _check_qty(self):
        for rec in self:
            if rec.qty < 0:
                # ValidationError for data-integrity rules (shown in the UI, rolls back)
                raise ValidationError(_("Quantity must be positive, got %s.", rec.qty))

    def action_do(self):
        self.ensure_one()                      # singleton guard before using self.<field>
        if not self.env.user.has_group('base.group_system'):
            raise AccessError(_("Only administrators can do this."))
        try:
            ...
        except Exception:                      # never a bare `except: pass`
            _logger.exception("x_thing: action_do failed for %s", self.id)
            raise UserError(_("The operation failed; see the server log."))

# Translations: `_("text %s", value)` — formatting args go INTO the call (lazy-safe).
# In model methods `self.env._("...")` is equivalent. Never f-string inside _().

from odoo import http
from odoo.http import request


class LibraryWebsite(http.Controller):

    # website page rendering a QWeb template (module 'website' in depends)
    @http.route('/library/books', type='http', auth='public', website=True, sitemap=True)
    def books(self, **kw):
        books = request.env['library.book'].sudo().search([('state', '=', 'available')])
        return request.render('x_library.website_books', {'books': books})

    # JSON endpoint (Odoo 18+: type='jsonrpc', the body is JSON-RPC)
    @http.route('/library/api/books', type='jsonrpc', auth='user', methods=['POST'])
    def api_books(self, limit=20, **kw):
        return request.env['library.book'].search_read([], ['name', 'state'], limit=limit)

    # file download
    @http.route('/library/export/<int:book_id>', type='http', auth='user')
    def export(self, book_id, **kw):
        book = request.env['library.book'].browse(book_id).exists()
        if not book:
            return request.not_found()
        data = f"name,state\n{book.name},{book.state}\n".encode()
        return request.make_response(data, headers=[
            ('Content-Type', 'text/csv'),
            ('Content-Disposition', http.content_disposition(f'book_{book.id}.csv')),
        ])

# website template (views/website_templates.xml):
