#     <t t-call="website.layout">
#         <div class="container my-4">
#             <t t-foreach="books" t-as="book"><p t-esc="book.name"/></t>
#         </div>
#     </t>
# </template>

/** @odoo-module **/
// static/src/fields/rating_stars/rating_stars.js
import { Component } from "@odoo/owl";
import { registry } from "@web/core/registry";
import { standardFieldProps } from "@web/views/fields/standard_field_props";
import { _t } from "@web/core/l10n/translation";

export class RatingStarsField extends Component {
    static template = "x_library.RatingStarsField";      // t-name in the .xml MUST match
    static props = { ...standardFieldProps, max: { type: Number, optional: true } };

    get value() {
        return this.props.record.data[this.props.name] || 0;
    }
    setValue(n) {
        this.props.record.update({ [this.props.name]: n });   // writes through the record
    }
}

export const ratingStarsField = {
    component: RatingStarsField,
    displayName: _t("Rating Stars"),
    supportedTypes: ["integer"],
    extractProps: ({ options }) => ({ max: options.max || 5 }),
};
registry.category("fields").add("rating_stars", ratingStarsField);

