/** @odoo-module **/
import { Component, onWillStart, useState } from "@odoo/owl";
import { registry } from "@web/core/registry";
import { useService } from "@web/core/utils/hooks";
import { _t } from "@web/core/l10n/translation";

export class LoanSystray extends Component {
    static template = "x_library.LoanSystray";
    static props = {};

    setup() {
        this.orm = useService("orm");
        this.action = useService("action");
        this.notification = useService("notification");
        this.state = useState({ count: 0 });
        onWillStart(async () => {
            // orm.call(model, method, args, kwargs) -> a @api.model / record method
            this.state.count = await this.orm.call("library.loan", "get_overdue_count", []);
        });
    }

    openOverdue() {
        this.action.doAction({
            type: "ir.actions.act_window",
            name: _t("Overdue loans"),
            res_model: "library.loan",
            views: [[false, "list"], [false, "form"]],
            domain: [["state", "=", "out"], ["date_due", "<", luxon.DateTime.now().toISODate()]],
        });
    }

    async remind() {
        await this.orm.call("library.loan", "action_send_all_reminders", []);
        this.notification.add(_t("Reminders sent"), { type: "success" });
    }
}
registry.category("systray").add("x_library.loan_systray", { Component: LoanSystray }, { sequence: 50 });

// Other services: useService("rpc") is GONE in 17+ — use `import { rpc } from "@web/core/network/rpc"`
// for raw routes; useService("user") -> `import { user } from "@web/core/user"` (user.userId, user.hasGroup()).

class LoanReturnWizard(models.TransientModel): _name = 'library.loan.return.wizard' _description = 'Return Loans'
loan_ids = fields.Many2many('library.loan', string='Loans') date_return = fields.Date(default=fields.Date.context_today, required=True)
@api.model def default_get(self, fields_list): res = super().default_get(fields_list) # opened from the list "Action" menu / a button: the selection is in the context if self.env.context.get('active_model') == 'library.loan': res['loan_ids'] = [(6, 0, self.env.context.get('active_ids', []))] return res
def action_confirm(self): self.ensure_one() self.loan_ids.write({'state': 'returned', 'date_return': self.date_return}) # close the dialog (or return an act_window to open something) return {'type': 'ir.actions.act_window_close'}
# views/wizard_views.xml # <record id="view_loan_return_wizard_form" model="ir.ui.view"> # <field name="name">library.loan.return.wizard.form</field> # <field name="model">library.loan.return.wizard</field> # <field name="arch" type="xml"> # <form> # <group><field name="date_return"/><field name="loan_ids" widget="many2many_tags"/></group> # <footer> # <button name="action_confirm" type="object" string="Return" class="btn-primary"/> # <button string="Cancel" class="btn-secondary" special="cancel"/> # </footer> # </form> # </field> # </record> # <record id="action_loan_return_wizard" model="ir.actions.act_window"> # <field name="name">Return Loans</field> # <field name="res_model">library.loan.return.wizard</field> # <field name="view_mode">form</field> # <field name="target">new</field> # <field name="binding_model_id" ref="model_library_loan"/> <!-- list "Action" menu --> # <field name="binding_view_types">list</field> # </record> # ir.model.access.csv needs a line for the TransientModel too.

# tests/__init__.py: from . import test_loan
# tests/test_loan.py
from odoo.tests import TransactionCase, HttpCase, tagged
from odoo.exceptions import UserError


@tagged('post_install', '-at_install')       # run after ALL modules are installed
class TestLoan(TransactionCase):

    @classmethod
    def setUpClass(cls):
        super().setUpClass()
        cls.book = cls.env['library.book'].create({'name': 'Test Book'})
        cls.partner = cls.env['res.partner'].create({'name': 'Reader'})

    def test_loan_flow(self):
        loan = self.env['library.loan'].create({'book_id': self.book.id, 'partner_id': self.partner.id})
        loan.action_confirm()
        self.assertEqual(loan.state, 'out')
        self.assertEqual(self.book.state, 'borrowed')
        with self.assertRaises(UserError):
            loan.unlink()


@tagged('post_install', '-at_install')
class TestLoanTour(HttpCase):
